<script lang="ts">
 import type {CategoryWeight} from '../types/municipality';import type {ConsumerCategoryFilters} from '../lib/consumerReal';import {activeConsumerFilterCount,defaultConsumerFilters} from '../lib/consumerReal';
 let {filters=$bindable(),weights,resultCount:_resultCount,open,onClose}:{filters:ConsumerCategoryFilters;weights:CategoryWeight[];resultCount:number;open:boolean;onClose:()=>void}=$props();
 const toggle=(category:string,active:boolean)=>{filters[category]=active?50:null;filters={...filters}};
</script>
{#if open}<button class="scrim" aria-label="Close park filters" onclick={onClose}></button>{/if}<aside class:open class="consumer-score-filters" aria-label="Park category score filters"><div class="filter-head"><div><p class="eyebrow">Find a park</p><h2>Choose what matters</h2></div><button class="close" onclick={onClose} aria-label="Close filters">×</button></div><p class="consumer-filter-intro">Find parks by their modelled scores for amenities, comfort, recreation, accessibility and greenery-related characteristics.</p><form class="category-filter-list">{#each weights as weight}<fieldset><div class="category-filter-head"><legend>{weight.label}</legend><label class="any-toggle"><input type="checkbox" checked={filters[weight.category]!==null} onchange={(e)=>toggle(weight.category,e.currentTarget.checked)}/><span>{filters[weight.category]===null?'Any':`Minimum ${filters[weight.category]}`}</span></label></div>{#if filters[weight.category]!==null}<input class="score-slider" type="range" min="0" max="100" step="5" aria-label={`Minimum ${weight.label} score`} bind:value={filters[weight.category]}/><div class="slider-scale"><span>0</span><output>{filters[weight.category]} / 100</output><span>100</span></div>{/if}</fieldset>{/each}</form><button class="clear" onclick={()=>filters=defaultConsumerFilters(weights)} disabled={activeConsumerFilterCount(filters)===0}>Clear all filters</button><p class="control-note">Scores are provisional estimates. Higher scores indicate stronger modelled characteristics, not verified facility availability.</p></aside>
